//! Files encrypted by the reference Go implementation (`age` 1.2.1;
//! `tests/fixtures/age/`, regenerated by `scripts/fixtures.sh`), decrypted
//! here. The other direction, this crate's files decrypted by `age`, needs
//! `age` installed: `scripts/interop.sh`, run in CI.

use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

use age::{decrypt, decrypt_seekable, parse_identities, Identity};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/age")
}

/// `scripts/plaintext.sh`: "sootmark\n" repeated, cut to `size`.
fn plaintext(size: usize) -> Vec<u8> {
    b"sootmark\n".iter().copied().cycle().take(size).collect()
}

fn identities() -> Vec<Identity> {
    parse_identities(&fs::read_to_string(fixtures().join("identity.txt")).unwrap()).unwrap()
}

#[test]
fn files_from_age_decrypt() {
    let identities = identities();
    let mut checked = 0;
    for entry in fs::read_dir(fixtures()).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let Some(stem) = name.strip_suffix(".age") else {
            continue;
        };
        let size: usize = stem.rsplit('-').next().unwrap().parse().unwrap();
        let file = fs::read(&path).unwrap();
        let mut out = Vec::new();
        decrypt(file.as_slice(), &identities)
            .unwrap_or_else(|error| panic!("{name}: {error}"))
            .read_to_end(&mut out)
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        assert!(out == plaintext(size), "{name}");
        let mut seekable = Vec::new();
        decrypt_seekable(std::io::Cursor::new(file), &identities)
            .unwrap_or_else(|error| panic!("{name}: {error}"))
            .read_to_end(&mut seekable)
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        assert!(seekable == out, "{name}: read in any order");
        checked += 1;
    }
    assert_eq!(checked, 7);
}

#[test]
fn age_keygen_and_this_crate_agree_on_the_public_key() {
    let text = fs::read_to_string(fixtures().join("identity.txt")).unwrap();
    let written = text
        .lines()
        .find_map(|line| line.strip_prefix("# public key: "))
        .unwrap();
    assert_eq!(identities()[0].to_public().to_string(), written);
}
